}

export function AbrufAnlegen({ positionId, fruehestens, offen }) {
  const { fehler, laeuft, los } = useSenden();
  const [d, setD] = useState({ betrag: "", faelligAm: fruehestens, zweck: "", meilenstein: "" });
  const setze = (k) => (e) => setD((x) => ({ ...x, [k]: e.target.value }));
  return (
    <form
      className="space-y-3"
      onSubmit={async (e) => {
        e.preventDefault();
